with enriched as (select id, txn_time, is_flagged, lag(amount) over (partition by merchant, txn_type order by amount, id) as prev_amount, row_number() over (partition by merchant, txn_type order by amount, id) as row_seq, sum(amount) over (partition by account_id order by amount, id rows between unbounded preceding and current row) as running_amount from transactions), metrics as (select id, is_flagged, row_seq, ntile(10) over (order by running_amount, id) as running_amount_bucket, ntile(5) over (order by running_amount, id) as running_amount_bucket_2, sum(row_seq) over (order by cast(txn_time as bigint) range between 2592000 preceding and current row) as row_seq_sum_30d from enriched where row_seq between 4 and 7), with_windows as (select id, is_flagged, running_amount_bucket_2, rank() over (order by running_amount_bucket_2) as running_amount_bucket_2_rank, lag(running_amount_bucket_2, 1) over (order by running_amount_bucket, id) as prev_running_amount_bucket_2 from metrics), valid as (select *, round(running_amount_bucket_2 * 1.1, 2) as running_amount_bucket_2_scaled from with_windows where prev_running_amount_bucket_2 >= 6), base as (select *, running_amount_bucket_2_scaled * running_amount_bucket_2 as running_amount_bucket_2_scaled_times_running_amount_bucket_2, case when is_flagged then 'Yes' else 'No' end as is_flagged_label from valid where running_amount_bucket_2 between 4 and 7) select case when prev_running_amount_bucket_2 >= 7 then 'PREMIUM' else 'STANDARD' end as prev_running_amount_bucket_2_tier, case when running_amount_bucket_2_scaled >= 83 then 'HIGH' else 'LOW' end as running_amount_bucket_2_scaled_tier, percentile_approx(running_amount_bucket_2, array(0.25, 0.5, 0.75)) as running_amount_bucket_2_quartiles, round(avg(running_amount_bucket_2_scaled_times_running_amount_bucket_2), 2) as avg_running_amount_bucket_2_scaled_times_running_amount_bucket_2, count(distinct id) as distinct_ids from base group by grouping sets ((case when prev_running_amount_bucket_2 >= 7 then 'PREMIUM' else 'STANDARD' end, case when running_amount_bucket_2_scaled >= 83 then 'HIGH' else 'LOW' end), (case when prev_running_amount_bucket_2 >= 7 then 'PREMIUM' else 'STANDARD' end)) having count(distinct id) >= 1 order by running_amount_bucket_2_scaled_tier desc
